package com.lifeos.events.dto; import com.lifeos.events.Event; import java.time.*; public record EventResponse(Long id,String title,String description,LocalDateTime startDateTime,LocalDateTime endDateTime,String location,LocalDateTime createdAt,LocalDateTime updatedAt){public static EventResponse from(Event e){return new EventResponse(e.getId(),e.getTitle(),e.getDescription(),e.getStartDateTime(),e.getEndDateTime(),e.getLocation(),e.getCreatedAt(),e.getUpdatedAt());}}
